//! Evaluates arithmetic expressions. See SPEC.md.

use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Error {
    /// A character that can't start a token, at this byte offset.
    UnexpectedChar(usize),
    /// The input ended where an operand or a closing parenthesis was needed.
    UnexpectedEnd,
    /// A token that doesn't fit the grammar, at the byte offset where it starts.
    UnexpectedToken(usize),
    UnknownVariable(String),
    UnknownFunction(String),
    /// A function called with the wrong number of arguments: (name, given).
    Arity(String, usize),
    DivisionByZero,
}

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Num(f64),
    Ident(String),
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Pow,
    LParen,
    RParen,
    Comma,
}

#[derive(Debug)]
enum Node {
    Num(f64),
    Var(String),
    Call(String, Vec<Node>),
    Neg(Box<Node>),
    Add(Box<Node>, Box<Node>),
    Sub(Box<Node>, Box<Node>),
    Mul(Box<Node>, Box<Node>),
    Div(Box<Node>, Box<Node>),
    Mod(Box<Node>, Box<Node>),
    Pow(Box<Node>, Box<Node>),
}

/// Evaluates `src` as one expression, looking up variables in `vars`.
pub fn eval(src: &str, vars: &HashMap<String, f64>) -> Result<f64, Error> {
    let mut p = Parser {
        lex: Lexer { src, pos: 0 },
        cur: None,
    };
    let node = p.parse()?;
    eval_node(&node, vars)
}

// ---------- tokenizer ----------

struct Lexer<'a> {
    src: &'a str,
    pos: usize,
}

impl<'a> Lexer<'a> {
    /// The character starting at byte offset `i`, if any.
    fn ch(&self, i: usize) -> Option<char> {
        self.src.get(i..).and_then(|s| s.chars().next())
    }

    fn skip_ws(&mut self) {
        while matches!(self.ch(self.pos), Some(' ' | '\t' | '\n' | '\r')) {
            self.pos += self.ch(self.pos).unwrap().len_utf8();
        }
    }

    /// Next token, or `None` at end of input. Errors when the character at the
    /// current position can't start any token.
    fn next(&mut self) -> Result<Option<(Tok, usize)>, Error> {
        self.skip_ws();
        let c = match self.ch(self.pos) {
            Some(c) => c,
            None => return Ok(None),
        };
        let start = self.pos;
        let b = c as u8;
        let one = |t: Tok| -> Result<Option<(Tok, usize)>, Error> {
            self.pos += c.len_utf8();
            Ok(Some((t, start)))
        };
        let t = if let Some(op) = match b {
            b'+' => Some(Tok::Add),
            b'-' => Some(Tok::Sub),
            b'*' => Some(Tok::Mul),
            b'/' => Some(Tok::Div),
            b'%' => Some(Tok::Mod),
            b'^' => Some(Tok::Pow),
            b'(' => Some(Tok::LParen),
            b')' => Some(Tok::RParen),
            b',' => Some(Tok::Comma),
            _ => None,
        } {
            one(op)?
        } else if c.is_ascii_digit() || c == '.' {
            self.number(start)?
        } else if c.is_alphabetic() || c == '_' {
            self.ident(start)?
        } else {
            return Err(Error::UnexpectedChar(start));
        };
        Ok(Some(t))
    }

    /// A number: digits with an optional fraction and an optional exponent.
    /// Needs at least one digit in the mantissa; an exponent without digits is
    /// not consumed (the letter stays available as an identifier).
    fn number(&mut self, start: usize) -> Result<(Tok, usize), Error> {
        let mut digits = 0usize;
        while self.ch(self.pos).map_or(false, |c| c.is_ascii_digit()) {
            self.pos += 1;
            digits += 1;
        }
        if self.ch(self.pos) == Some('.') {
            self.pos += 1;
            while self.ch(self.pos).map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
                digits += 1;
            }
        }
        if matches!(self.ch(self.pos), Some('e' | 'E')) {
            let mut i = self.pos + 1;
            if matches!(self.ch(i), Some('+' | '-')) {
                i += 1;
            }
            let mut exp = 0usize;
            while self.ch(i).map_or(false, |c| c.is_ascii_digit()) {
                i += 1;
                exp += 1;
            }
            if exp > 0 {
                self.pos = i;
            }
        }
        if digits == 0 {
            return Err(Error::UnexpectedChar(start));
        }
        let text = &self.src[start..self.pos];
        let v = text.parse::<f64>().unwrap();
        Ok((Tok::Num(v), start))
    }

    /// An identifier: a letter or `_`, then letters, digits or `_`.
    fn ident(&mut self, start: usize) -> (Tok, usize) {
        loop {
            match self.ch(self.pos) {
                Some(c) if c.is_alphanumeric() || c == '_' => self.pos += c.len_utf8(),
                _ => break,
            }
        }
        let name = self.src[start..self.pos].to_string();
        (Tok::Ident(name), start)
    }
}

// ---------- parser ----------

struct Parser<'a> {
    lex: Lexer<'a>,
    cur: Option<(Tok, usize)>,
}

impl<'a> Parser<'a> {
    fn peek(&mut self) -> Result<Option<(Tok, usize)>, Error> {
        if self.cur.is_none() {
            self.cur = self.lex.next()?;
        }
        Ok(self.cur.clone())
    }

    fn bump(&mut self) -> Result<Option<(Tok, usize)>, Error> {
        if self.cur.is_none() {
            self.cur = self.lex.next()?;
        }
        Ok(self.cur.take())
    }

    /// Whole input: one expression, then end.
    fn parse(&mut self) -> Result<Node, Error> {
        let node = self.parse_expr()?;
        match self.peek()? {
            None => Ok(node),
            Some((_, pos)) => Err(Error::UnexpectedToken(pos)),
        }
    }

    // `+ -`, left associative.
    fn parse_expr(&mut self) -> Result<Node, Error> {
        let mut left = self.parse_mul()?;
        loop {
            match self.peek()? {
                Some((Tok::Add, _)) => {
                    self.bump()?;
                    let r = self.parse_mul()?;
                    left = Node::Add(Box::new(left), Box::new(r));
                }
                Some((Tok::Sub, _)) => {
                    self.bump()?;
                    let r = self.parse_mul()?;
                    left = Node::Sub(Box::new(left), Box::new(r));
                }
                _ => break,
            }
        }
        Ok(left)
    }

    // `* / %`, left associative.
    fn parse_mul(&mut self) -> Result<Node, Error> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match self.peek()? {
                Some((Tok::Mul, _)) => {
                    self.bump()?;
                    Some(Node::Mul)
                }
                Some((Tok::Div, _)) => {
                    self.bump()?;
                    Some(Node::Div)
                }
                Some((Tok::Mod, _)) => {
                    self.bump()?;
                    Some(Node::Mod)
                }
                _ => None,
            };
            let Some(op) = op else { break };
            let r = self.parse_unary()?;
            left = match op {
                Node::Mul => Node::Mul(Box::new(left), Box::new(r)),
                Node::Div => Node::Div(Box::new(left), Box::new(r)),
                Node::Mod => Node::Mod(Box::new(left), Box::new(r)),
                _ => unreachable!(),
            };
        }
        Ok(left)
    }

    // unary `+ -`, repeatable; below `^` in precedence.
    fn parse_unary(&mut self) -> Result<Node, Error> {
        match self.peek()? {
            Some((Tok::Add, _)) => {
                self.bump()?;
                self.parse_unary()
            }
            Some((Tok::Sub, _)) => {
                self.bump()?;
                Ok(Node::Neg(Box::new(self.parse_unary()?)))
            }
            _ => self.parse_power(),
        }
    }

    // `^`, right associative, tighter than unary: the exponent is a unary
    // expression, the base is an atom.
    fn parse_power(&mut self) -> Result<Node, Error> {
        let base = self.parse_atom()?;
        if matches!(self.peek()?, Some((Tok::Pow, _))) {
            self.bump()?;
            let exp = self.parse_unary()?;
            Ok(Node::Pow(Box::new(base), Box::new(exp)))
        } else {
            Ok(base)
        }
    }

    // numbers, identifiers, calls, parenthesized expressions.
    fn parse_atom(&mut self) -> Result<Node, Error> {
        match self.bump()? {
            None => Err(Error::UnexpectedEnd),
            Some((Tok::Num(v), _)) => Ok(Node::Num(v)),
            Some((Tok::Ident(name), _)) => {
                if matches!(self.peek()?, Some((Tok::LParen, _))) {
                    self.bump()?;
                    let mut args = vec![self.parse_expr()?];
                    loop {
                        match self.peek()? {
                            Some((Tok::Comma, _)) => {
                                self.bump()?;
                                args.push(self.parse_expr()?);
                            }
                            Some((Tok::RParen, _)) => {
                                self.bump()?;
                                break;
                            }
                            Some((_, pos)) => return Err(Error::UnexpectedToken(pos)),
                            None => return Err(Error::UnexpectedEnd),
                        }
                    }
                    Ok(Node::Call(name, args))
                } else {
                    Ok(Node::Var(name))
                }
            }
            Some((Tok::LParen, _)) => {
                let e = self.parse_expr()?;
                match self.bump()? {
                    Some((Tok::RParen, _)) => Ok(e),
                    Some((_, pos)) => Err(Error::UnexpectedToken(pos)),
                    None => Err(Error::UnexpectedEnd),
                }
            }
            Some((_, pos)) => Err(Error::UnexpectedToken(pos)),
        }
    }
}

// ---------- evaluation ----------

fn eval_node(node: &Node, vars: &HashMap<String, f64>) -> Result<f64, Error> {
    match node {
        Node::Num(v) => Ok(*v),
        Node::Var(name) => vars
            .get(name)
            .copied()
            .ok_or_else(|| Error::UnknownVariable(name.clone())),
        Node::Neg(x) => Ok(-eval_node(x, vars)?),
        Node::Add(l, r) => Ok(eval_node(l, vars)? + eval_node(r, vars)?),
        Node::Sub(l, r) => Ok(eval_node(l, vars)? - eval_node(r, vars)?),
        Node::Mul(l, r) => Ok(eval_node(l, vars)? * eval_node(r, vars)?),
        Node::Div(l, r) => {
            let a = eval_node(l, vars)?;
            let b = eval_node(r, vars)?;
            if b == 0.0 {
                return Err(Error::DivisionByZero);
            }
            Ok(a / b)
        }
        Node::Mod(l, r) => {
            let a = eval_node(l, vars)?;
            let b = eval_node(r, vars)?;
            if b == 0.0 {
                return Err(Error::DivisionByZero);
            }
            Ok(a % b)
        }
        Node::Pow(l, r) => Ok(eval_node(l, vars)?.powf(eval_node(r, vars)?)),
        Node::Call(name, args) => {
            match name.as_str() {
                "abs" => {
                    if args.len() != 1 {
                        return Err(Error::Arity(name.clone(), args.len()));
                    }
                    Ok(eval_node(&args[0], vars)?.abs())
                }
                "sqrt" => {
                    if args.len() != 1 {
                        return Err(Error::Arity(name.clone(), args.len()));
                    }
                    Ok(eval_node(&args[0], vars)?.sqrt())
                }
                "min" | "max" => {
                    if args.is_empty() {
                        return Err(Error::Arity(name.clone(), args.len()));
                    }
                    let mut it = args.iter();
                    let mut acc = eval_node(it.next().unwrap(), vars)?;
                    for a in it {
                        let v = eval_node(a, vars)?;
                        acc = if name == "min" { acc.min(v) } else { acc.max(v) };
                    }
                    Ok(acc)
                }
                _ => Err(Error::UnknownFunction(name.clone())),
            }
        }
    }
}

//! Tests for the expression language in SPEC.md.

use calc::{eval, Error};
use std::collections::HashMap;

fn vars(pairs: &[(&str, f64)]) -> HashMap<String, f64> {
    pairs.iter().copied().map(|(k, v)| (k.to_string(), v)).collect()
}

fn ok(src: &str, v: &HashMap<String, f64>) -> f64 {
    eval(src, v).unwrap_or_else(|e| panic!("{src:?} => Err({e:?}), expected a value"))
}

/// Approximate equality, tight enough for the values in this spec.
fn check(src: &str, v: &HashMap<String, f64>, want: f64) {
    let got = ok(src, v);
    assert!(
        (got - want).abs() <= 1e-9 * want.abs().max(1.0),
        "{src:?}: got {got}, want {want}"
    );
}

fn check_exact(src: &str, v: &HashMap<String, f64>, want: f64) {
    assert_eq!(ok(src, v), want, "for {src:?}");
}

fn check_err(src: &str, v: &HashMap<String, f64>, want: Error) {
    let got = eval(src, v).unwrap_or_else(|_| panic!("{src:?} => Ok, expected Err({want:?})"));
    assert_eq!(got, want, "for {src:?}");
}

fn empty() -> HashMap<String, f64> {
    HashMap::new()
}

// ---------- numbers ----------

#[test]
fn number_literals() {
    check_exact("3", &empty(), 3.0);
    check_exact("3.25", &empty(), 3.25);
    check_exact(".5", &empty(), 0.5);
    check_exact("2e3", &empty(), 2000.0);
    check_exact("1.5E-2", &empty(), 0.015);
    check_exact("2E3", &empty(), 2000.0);
    check_exact("2e+3", &empty(), 2000.0);
    check_exact(".5e2", &empty(), 50.0);
    check_exact("1.e3", &empty(), 1000.0); // `1.` is a number, `e3` its exponent
}

// ---------- operators and precedence ----------

#[test]
fn arithmetic() {
    check_exact("1 + 2 * 3", &empty(), 7.0);
    check_exact("(1 + 2) * 3", &empty(), 9.0);
    check_exact("10 - 4 - 3", &empty(), 3.0); // left associative
    check_exact("100 / 5 / 2", &empty(), 10.0); // left associative
    check_exact("1 + 2 * 3 - 4", &empty(), 3.0);
    check_exact("2 + 3 * 4 ^ 2", &empty(), 50.0);
    check_exact("2 * 3 ^ 2", &empty(), 18.0);
    check_exact("(2 + 3) * (4 - 1)", &empty(), 15.0);
}

#[test]
fn remainder() {
    check_exact("7 % 3", &empty(), 1.0);
    check_exact("-7 % 3", &empty(), -1.0); // sign of the dividend
    check_exact("7 % -3", &empty(), 1.0);
    check_exact("-7 % -3", &empty(), -1.0);
    check_exact("10 % 4", &empty(), 2.0);
    check_exact("1 + 7 % 3", &empty(), 2.0);
}

// ---------- unary and ^ ----------

#[test]
fn unary() {
    check_exact("-2", &empty(), -2.0);
    check_exact("+2", &empty(), 2.0);
    check_exact("--2", &empty(), 2.0);
    check_exact("---2", &empty(), -2.0);
    check_exact("-+2", &empty(), -2.0);
    check_exact("- - 2", &empty(), 2.0);
    check_exact("2 * -3", &empty(), -6.0);
    check_exact("-2 * 3", &empty(), -6.0);
}

#[test]
fn power() {
    // ^ binds tighter than unary minus: -2^2 is -(2^2)
    check_exact("-2^2", &empty(), -4.0);
    check_exact("--2^2", &empty(), 4.0);
    // the exponent of ^ is a unary expression: 2^-1 is 0.5
    check_exact("2^-1", &empty(), 0.5);
    // right associative: 2^3^2 is 2^(3^2)
    check_exact("2^3^2", &empty(), 512.0);
    check_exact("2^2^3", &empty(), 256.0);
    check_exact("2 ^ -3 ^ 2", &empty(), 2.0f64.powf(-9.0));
    check_exact("-2^2 * 3", &empty(), -12.0);
    check_exact("2 * -3 ^ 2", &empty(), -18.0);
    check_exact("(1 + 2)^2", &empty(), 9.0);
    check_exact("abs(9)^2", &empty(), 9.0);
    check("2 ^ 0.5", &empty(), 2f64.sqrt());
}

// ---------- whitespace ----------

#[test]
fn whitespace_is_ignored() {
    let v = vars(&[("x", 2.0), ("y", 3.0)]);
    check_exact("  x  +  y ", &v, 5.0);
    check_exact("\t1\n+2\r", &empty(), 3.0);
    check_exact("( 1 + 2 )", &empty(), 3.0);
    check_exact("min( 1 ,2, 3 )", &empty(), 1.0);
}

// ---------- identifiers and variables ----------

#[test]
fn variables() {
    let v = vars(&[("x", 2.0), ("y", 3.0), ("_a1", 4.0), ("a_b", 5.0)]);
    check_exact("x + y", &v, 5.0);
    check_exact("_a1 + a_b", &v, 9.0);
    check_exact("x*2", &v, 4.0);
    // `e` is a variable name, not the start of a number
    let v = vars(&[("e", 7.0)]);
    check_exact("e + 1", &v, 8.0);
}

// ---------- functions ----------

#[test]
fn functions() {
    check_exact("abs(-5)", &empty(), 5.0);
    check_exact("abs(3)", &empty(), 3.0);
    check_exact("sqrt(16)", &empty(), 4.0);
    check_exact("min(3, 1, 2)", &empty(), 1.0);
    check_exact("max(3, 1, 2)", &empty(), 3.0);
    check_exact("min(5)", &empty(), 5.0);
    check_exact("max(5)", &empty(), 5.0);
    check_exact("min(1, 2) + max(3)", &empty(), 4.0);
    check_exact("abs(abs(-2) + 1)", &empty(), 3.0);
    check_exact("min(max(1, 2), 3)", &empty(), 2.0);
    check_exact("min(1, 2, 3) * max(4, 5)", &empty(), 5.0);
    check_exact("-sqrt(16)", &empty(), -4.0);
    check("sqrt(2) * sqrt(2)", &empty(), 2.0);
}

// ---------- errors: tokenization ----------

#[test]
fn unexpected_char() {
    check_err("2 $ 3", &empty(), Error::UnexpectedChar(2));
    check_err("a $ b", &empty(), Error::UnexpectedChar(2));
    check_err("#", &empty(), Error::UnexpectedChar(0));
    // a `.` that starts no number is an unexpected character
    check_err("2 . 3", &empty(), Error::UnexpectedChar(2));
    // an exponent without digits leaves `e` an identifier in the wrong place
    check_err("2e", &empty(), Error::UnexpectedToken(1));
}

// ---------- errors: end of input ----------

#[test]
fn unexpected_end() {
    check_err("", &empty(), Error::UnexpectedEnd);
    check_err("2 +", &empty(), Error::UnexpectedEnd);
    check_err("(1", &empty(), Error::UnexpectedEnd);
    check_err("min(1,", &empty(), Error::UnexpectedEnd);
    check_err("2 + (3", &empty(), Error::UnexpectedEnd);
    check_err("min(1, 2", &empty(), Error::UnexpectedEnd);
    check_err("2 -", &empty(), Error::UnexpectedEnd);
    check_err("2 *", &empty(), Error::UnexpectedEnd);
    check_err("2 ^", &empty(), Error::UnexpectedEnd);
}

// ---------- errors: misplaced tokens ----------

#[test]
fn unexpected_token() {
    check_err(")", &empty(), Error::UnexpectedToken(0));
    check_err("(1))", &empty(), Error::UnexpectedToken(3));
    check_err("2 3", &empty(), Error::UnexpectedToken(2));
    check_err("()", &empty(), Error::UnexpectedToken(1));
    check_err("1 + (2 3)", &empty(), Error::UnexpectedToken(6));
    check_err("min(1 2)", &empty(), Error::UnexpectedToken(6));
    check_err("2 , 3", &empty(), Error::UnexpectedToken(2));
    check_err("(1, 2)", &empty(), Error::UnexpectedToken(1));
    check_err("1 + + 2", &empty(), Error::UnexpectedToken(4));
}

// ---------- errors: evaluation ----------

#[test]
fn unknown_variable() {
    check_err("x", &empty(), Error::UnknownVariable("x".into()));
    let v = vars(&[("x", 1.0)]);
    check_err("x / y", &v, Error::UnknownVariable("y".into()));
    // evaluation errors only come after the whole input has parsed
    check_err("1 / 0 + x", &empty(), Error::DivisionByZero);
    check_err("x / 0", &empty(), Error::UnknownVariable("x".into()));
    check_err("1 / 0 + x + )", &empty(), Error::UnexpectedToken(11));
}

#[test]
fn unknown_function() {
    check_err("foo(1)", &empty(), Error::UnknownFunction("foo".into()));
    check_err("foo(1) / 0", &empty(), Error::UnknownFunction("foo".into()));
    // an identifier followed by `(` is a call, even if the name looks like a variable
    let v = vars(&[("min", 4.0)]);
    check_err("min(1)", &v, Error::Arity("min".into(), 1));
}

#[test]
fn arity() {
    check_err("abs()", &empty(), Error::Arity("abs".into(), 0));
    check_err("abs(1, 2)", &empty(), Error::Arity("abs".into(), 2));
    check_err("sqrt()", &empty(), Error::Arity("sqrt".into(), 0));
    check_err("sqrt(1, 2)", &empty(), Error::Arity("sqrt".into(), 2));
    check_err("min()", &empty(), Error::Arity("min".into(), 0));
    check_err("max()", &empty(), Error::Arity("max".into(), 0));
    check_err("abs(1, 1/0)", &empty(), Error::Arity("abs".into(), 2));
}

#[test]
fn division_by_zero() {
    check_err("1 / 0", &empty(), Error::DivisionByZero);
    check_err("1 % 0", &empty(), Error::DivisionByZero);
    check_err("0 / 0", &empty(), Error::DivisionByZero);
    check_err("1 / (2 - 2)", &empty(), Error::DivisionByZero);
    check_err("2 ^ (1 / 0)", &empty(), Error::DivisionByZero);
    check_err("min(1/0, 2)", &empty(), Error::DivisionByZero);
    check_err("min(1, 2) % 0", &empty(), Error::DivisionByZero);
}

// ---------- error precedence: first found reading left to right ----------

#[test]
fn first_error_wins() {
    check_err("2 $ +", &empty(), Error::UnexpectedChar(2));
    check_err("(1 + 2 $)", &empty(), Error::UnexpectedChar(7));
    check_err(") $", &empty(), Error::UnexpectedToken(0));
}

