324: fn eval_node(node: &Node, vars: &HashMap<String, f64>) -> Result<f64, Error> {
325:     match node {
326:         Node::Num(v) => Ok(*v),
327:         Node::Var(name) => vars
328:             .get(name)
329:             .copied()
330:             .ok_or_else(|| Error::UnknownVariable(name.clone())),
331:         Node::Neg(x) => Ok(-eval_node(x, vars)?),
332:         Node::Add(l, r) => Ok(eval_node(l, vars)? + eval_node(r, vars)?),
333:         Node::Sub(l, r) => Ok(eval_node(l, vars)? - eval_node(r, vars)?),
334:         Node::Mul(l, r) => Ok(eval_node(l, vars)? * eval_node(r, vars)?),
335:         Node::Div(l, r) => {
336:             let a = eval_node(l, vars)?;
337:             let b = eval_node(r, vars)?;
338:             if b == 0.0 {
339:                 return Err(Error::DivisionByZero);
340:             }
341:             Ok(a / b)
342:         }
343:         Node::Mod(l, r) => {
344:             let a = eval_node(l, vars)?;
345:             let b = eval_node(r, vars)?;
346:             if b == 0.0 {
347:                 return Err(Error::DivisionByZero);
348:             }
349:             Ok(a % b)
350:         }
351:         Node::Pow(l, r) => Ok(eval_node(l, vars)?.powf(eval_node(r, vars)?)),
352:         Node::Call(name, args) => {
353:             match name.as_str() {
354:                 "abs" => {
355:                     if args.len() != 1 {
356:                         return Err(Error::Arity(name.clone(), args.len()));
357:                     }
358:                     Ok(eval_node(&args[0], vars)?.abs())
359:                 }
360:                 "sqrt" => {
361:                     if args.len() != 1 {
362:                         return Err(Error::Arity(name.clone(), args.len()));
363:                     }
364:                     Ok(eval_node(&args[0], vars)?.sqrt())
365:                 }
366:                 "min" | "max" => {
367:                     if args.is_empty() {
368:                         return Err(Error::Arity(name.clone(), args.len()));
369:                     }
370:                     let mut it = args.iter();
371:                     let mut acc = eval_node(it.next().unwrap(), vars)?;
372:                     for a in it {
373:                         let v = eval_node(a, vars)?;
374:                         acc = if name == "min" { acc.min(v) } else { acc.max(v) };
375:                     }
376:                     Ok(acc)
377:                 }
378:                 _ => Err(Error::UnknownFunction(name.clone())),
379:             }
380:         }
381:     }
382: }
